from decimal import Decimal
from typing import Any


def _value(record: dict[str, Any] | None, field: str) -> Any:
    if record is None:
        return ""
    return record.get(field, "")


def _text(value: Any) -> str:
    if value is None:
        return ""
    return value if isinstance(value, str) else str(value)


def _length(value: Any) -> int:
    return len(_text(value)) if value not in ("", None) else 0


def _number(value: Any) -> Decimal:
    if value == "" or value is None:
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict[str, str]:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = {}

    failures: list[dict] = []

    # ACC-001
    if event in ("INSERT", "UPDATE"):
        if not (_length(_value(record, "ACCT_NM")) >= 2):
            failures.append(_failure("E1001", "Account name too short"))

    # ACC-002
    if event in ("INSERT", "UPDATE"):
        if _value(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            failures.append(_failure("E1002", "Invalid account type"))

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        if not (_number(_value(record, "ANN_REV")) >= Decimal(0)):
            failures.append(_failure("E1003", "Annual revenue negative"))

    # ACC-004
    if event == "UPDATE":
        old_hold = _value(old, "CRED_HOLD")
        new_hold = _value(record, "CRED_HOLD")
        credit_limit = _number(_value(record, "CRED_LIMIT"))
        condition = (
            old_hold == "Y"
            and new_hold == "N"
            and credit_limit <= Decimal(0)
        )
        if condition:
            failures.append(
                _failure(
                    "E1004",
                    "Cannot release credit hold with zero credit limit",
                )
            )

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if not (_length(_value(record, "REGION_CD")) == 3):
            failures.append(
                _failure(
                    "E1005",
                    "Region code must be 3 chars",
                    "WARN",
                )
            )

    return failures


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
